parameters.jsCode:
return [
  {
    json: {
      requirement: $input.first().json.requirement || "I need an AI LinkedIn Content Automation"
    }
  }
];

parameters.inputSchema:
{
  "type": "object",
  "properties": {

    "business_problem": {
      "type": "string",
      "description": "Main business problem identified from user requirement"
    },

    "automation_need": {
      "type": "string",
      "description": "What automation is required to solve the business problem"
    },

    "matched_workflow": {
      "type": "object",
      "description": "Existing workflow found from knowledge base",
      "properties": {

        "workflow_name": {
          "type": "string",
          "description": "Exact workflow name from Qdrant metadata. Do not modify."
        },

        "workflow_category": {
          "type": "string",
          "description": "Category of matched workflow"
        },

        "match_score": {
          "type": "string",
          "description": "Similarity confidence score"
        },

        "matching_reason": {
          "type": "string",
          "description": "Why this workflow matches user requirement"
        }

      },
      "required": [
        "workflow_name",
        "workflow_category",
        "match_score",
        "matching_reason"
      ]
    },

    "recommended_solution": {
      "type": "string",
      "description": "Recommended automation solution based on knowledge base workflow"
    },

    "workflow_architecture": {
      "type": "string",
      "description": "High level workflow architecture and components flow"
    },

    "required_components": {
      "type": "array",
      "description": "Required tools and technologies",
      "items": {
        "type": "string"
      }
    },

    "implementation_steps": {
      "type": "array",
      "description": "Steps required to implement this automation",
      "items": {
        "type": "string"
      }
    },

    "estimated_complexity": {
      "type": "string",
      "description": "Implementation difficulty level"
    },

    "estimated_cost": {
      "type": "string",
      "description": "Approximate automation cost"
    },

    "business_impact": {
      "type": "string",
      "description": "Expected business benefit"
    },

    "next_action": {
      "type": "string",
      "description": "Recommended next step after consultation"
    }

  },

  "required": [
    "business_problem",
    "automation_need",
    "matched_workflow",
    "recommended_solution",
    "workflow_architecture",
    "required_components",
    "implementation_steps",
    "estimated_complexity",
    "estimated_cost",
    "business_impact",
    "next_action"
  ]
}
